function fmtDate(iso) {
  return new Date(iso).toLocaleDateString('vi-VN', {
    day: '2-digit', month: 'long', year: 'numeric',
  });
}

/**
 * Render Tiptap JSON doc as readable HTML.
 * ponytail: basic node-to-html mapper; upgrade to @tiptap/html if more nodes needed.
 */
function TiptapRender({ content }) {
  if (!content) return null;
  let doc;
  try {
    doc = typeof content === 'string' ? JSON.parse(content) : content;
  } catch {
    return <p className="text-[#d1d5db] whitespace-pre-wrap">{content}</p>;
  }

  const renderNode = (node, idx) => {
    if (!node) return null;
    const children = node.content?.map((c, i) => renderNode(c, i));
    switch (node.type) {
      case 'doc': return <>{children}</>;
      case 'paragraph': return <p key={idx} className="mb-3 text-[#d1d5db] leading-relaxed">{children}</p>;
      case 'heading': return React.createElement(`h${node.attrs?.level ?? 2}`, { key: idx, className: 'font-playfair font-bold text-[#f3f4f6] mt-5 mb-2 text-xl' }, children);
      case 'bulletList': return <ul key={idx} className="list-disc pl-5 mb-3 text-[#d1d5db] space-y-1">{children}</ul>;
      case 'orderedList': return <ol key={idx} className="list-decimal pl-5 mb-3 text-[#d1d5db] space-y-1">{children}</ol>;
      case 'listItem': return <li key={idx}>{children}</li>;
      case 'blockquote': return <blockquote key={idx} className="border-l-4 border-[#d4af37]/50 pl-4 italic text-[#9ca3af] my-3">{children}</blockquote>;
      case 'hardBreak': return <br key={idx} />;
      case 'image': return (
        <img key={idx} src={node.attrs?.src} alt={node.attrs?.alt ?? ''} className="max-w-full rounded-lg my-4 border border-[#2d323f]" />
      );
      case 'text': {
        let el = <>{node.text}</>;
        (node.marks ?? []).forEach(mark => {
          if (mark.type === 'bold') el = <strong className="font-bold text-[#f3f4f6]">{el}</strong>;
          if (mark.type === 'italic') el = <em>{el}</em>;
          if (mark.type === 'strike') el = <s>{el}</s>;
          if (mark.type === 'code') el = <code className="bg-[#0d0e12] px-1 py-0.5 rounded text-[#d4af37] font-mono text-sm">{el}</code>;
        });
        return <React.Fragment key={idx}>{el}</React.Fragment>;
      }
      default: return <React.Fragment key={idx}>{children}</React.Fragment>;
    }
  };

  return <div>{renderNode(doc)}</div>;
}

const STATUS_BADGE = {
  PENDING: { labelKey: 'forum:pending', cls: 'bg-yellow-900/50 text-yellow-300 border-yellow-600/40' },
  APPROVED: { labelKey: 'forum:approved', cls: 'bg-emerald-900/50 text-emerald-300 border-emerald-600/40' },
  DENIED: { labelKey: 'forum:denied', cls: 'bg-red-900/50 text-red-300 border-red-600/40' },
};

/**
 * PostDetailPage — chi tiết bài viết + comments + replies.
 * Layout Header & Footer được đảm nhận bởi PublicLayout.
 */
export default function PostDetailPage() {
  const { id } = useParams();
  const { t } = useTranslation(['forum']);
  const queryClient = useQueryClient();
  const { isAuthenticated, currentUser } = useAuth();
  const canInteract = isAuthenticated && currentUser?.role !== 'GUEST';

  // Post
  const { data: post, isLoading: postLoading, isError: postError } = useQuery({
    queryKey: ['post', id],
    queryFn: () => forumService.getPost(id),
    retry: false,
  });

  // Local liked/likeCount for optimistic UI
  const [localLiked, setLocalLiked] = useState(null);
  const [localLikeCount, setLocalLikeCount] = useState(null);

  const liked = localLiked ?? post?.liked ?? false;
  const likeCount = localLikeCount ?? post?.likeCount ?? 0;

  const handleLikePost = async () => {
    const newLiked = !liked;
    setLocalLiked(newLiked);
    setLocalLikeCount(c => newLiked ? (c ?? likeCount) + 1 : Math.max(0, (c ?? likeCount) - 1));
    try {
      await forumService.likePost(id, newLiked);
    } catch {
      setLocalLiked(!newLiked);
      setLocalLikeCount(likeCount);
    }
  };

  // Comments (infinite)
  const {
    data: commentsData,
    fetchNextPage: fetchMoreComments,
    hasNextPage: hasMoreComments,
    isFetchingNextPage: loadingMoreComments,
    isLoading: commentsLoading,
  } = useInfiniteQuery({
    queryKey: ['comments', id],
    queryFn: ({ pageParam = 0 }) => forumService.getComments(id, pageParam, 10),
    initialPageParam: 0,
    getNextPageParam: (last) => {
      const { number, totalPages } = last.page ?? {};
      return number < totalPages - 1 ? number + 1 : undefined;
    },
    enabled: !!post,
  });

  const allComments = commentsData?.pages.flatMap(p => p.content) ?? [];

  const handleAddComment = async (body) => {
    const newComment = await forumService.createComment(body);
    // Prepend to first page cache
    queryClient.setQueryData(['comments', id], (old) => ({
      ...old,
      pages: old?.pages
        ? [{ ...old.pages[0], content: [newComment, ...old.pages[0].content] }, ...old.pages.slice(1)]
        : old,
    }));
  };

  if (postLoading) return (
    <div className="flex-1 flex items-center justify-center py-20">
      <RefreshCw className="w-8 h-8 text-[#d4af37] animate-spin" />
    </div>
  );

  if (postError || !post) return (
    <div className="flex-1 flex flex-col items-center justify-center text-[#9ca3af] gap-4 py-20">
      <p className="text-lg font-semibold text-[#f3f4f6]">{t('forum:post_not_found')}</p>
      <p className="text-sm">{t('forum:post_not_exists')}</p>
      <Link to="/forum" className="text-[#d4af37] text-sm hover:underline">← {t('forum:back_to_forum')}</Link>
    </div>
  );

  const badge = STATUS_BADGE[post.status];

  return (
    <main className="w-full max-w-3xl mx-auto px-4 py-10">
      {/* Back */}
      <Link
        to="/forum"
        className="inline-flex items-center gap-2 text-sm text-[#9ca3af] hover:text-[#f3f4f6] mb-6 transition-colors"
      >
        <ArrowLeft className="w-4 h-4" />
        Forum
      </Link>

      {/* Article */}
      <article id={`post-detail-${id}`} className="bg-[#1a1d24] border border-[#2d323f] rounded-2xl p-6 md:p-8 mb-8">
        {/* Status + meta */}
        <div className="flex flex-wrap items-center gap-3 mb-4">
          {badge && (
            <span className={`text-[10px] font-semibold px-2 py-0.5 rounded border ${badge.cls}`}>
              {t(badge.labelKey)}
            </span>
          )}
          <div className="flex items-center gap-1.5 text-xs text-[#9ca3af]">
            <Calendar className="w-3.5 h-3.5" />
            {post.createdAt ? fmtDate(post.createdAt) : ''}
          </div>
          <div className="flex items-center gap-1.5 text-xs text-[#9ca3af]">
            <Eye className="w-3.5 h-3.5" />
            {post.viewCount ?? 0} {t('forum:views_count_text')}
          </div>
        </div>

        {/* Title */}
        <h1 className="font-playfair text-2xl md:text-3xl font-bold text-[#f3f4f6] mb-4 leading-tight">
          {post.title}
        </h1>

        {/* Author */}
        <div className="flex items-center gap-2.5 pb-6 border-b border-[#2d323f] mb-6">
          <div className="w-9 h-9 rounded-full border border-[#d4af37]/30 bg-[#0d0e12] flex items-center justify-center overflow-hidden shrink-0">
            {post.author?.avatarUrl
              ? <img src={post.author.avatarUrl} alt={post.author.username} className="w-full h-full object-cover" />
              : <User className="w-4 h-4 text-[#d4af37]" />}
          </div>
          <span className="text-sm font-semibold text-[#f3f4f6]">{post.author?.username ?? t('forum:anonymous')}</span>
        </div>

        {/* Content */}
        <div className="mb-6">
          <TiptapRender content={post.content} />
        </div>

        {/* Actions */}
        <div className="flex items-center gap-4 pt-4 border-t border-[#2d323f]">
          {canInteract ? (
            <LikeButton
              liked={liked}
              count={likeCount}
              onClick={handleLikePost}
              size="md"
            />
          ) : (
            <span className="flex items-center gap-1.5 text-sm text-[#9ca3af]">
              <LikeButton liked={liked} count={likeCount} disabled size="md" />
            </span>
          )}
        </div>
      </article>

      {/* Comments section */}
      <section id="comments-section">
        <h2 className="font-playfair text-xl font-bold text-[#f3f4f6] mb-5">
          {t('forum:comments_title')} {post.commentCount ? `(${post.commentCount})` : ''}
        </h2>

        {/* Comment form */}
        {canInteract ? (
          <div className="mb-6">
            <CommentForm postId={id} onSubmit={handleAddComment} />
          </div>
        ) : (
          <div className="mb-6 flex items-center gap-2 px-4 py-3 rounded-xl border border-[#2d323f] bg-[#1a1d24] text-sm text-[#9ca3af]">
            <Lock className="w-4 h-4 shrink-0" />
            <span>
              {isAuthenticated
                ? t('forum:guest_cannot_comment')
                : <><Link to="/login" className="text-[#d4af37] hover:underline">{t('forum:login')}</Link>{t('forum:to_comment')}</>}
            </span>
          </div>
        )}

        {/* Comments list */}
        {commentsLoading ? (
          <div className="space-y-4">
            {[1, 2, 3].map(i => (
              <div key={i} className="flex gap-3 animate-pulse">
                <div className="w-8 h-8 rounded-full bg-[#2d323f] shrink-0" />
                <div className="flex-1 space-y-2">
                  <div className="h-3 w-24 bg-[#2d323f] rounded" />
                  <div className="h-3 w-full bg-[#2d323f] rounded" />
                  <div className="h-3 w-3/4 bg-[#2d323f] rounded" />
                </div>
              </div>
            ))}
          </div>
        ) : allComments.length === 0 ? (
          <p className="text-sm text-[#9ca3af] text-center py-8">{t('forum:no_comments_yet')}</p>
        ) : (
          <div className="divide-y divide-[#2d323f]">
            {allComments.map(comment => (
              <CommentItem
                key={comment.id}
                comment={comment}
                postId={id}
                isAuth={canInteract}
                onAddComment={handleAddComment}
              />
            ))}
          </div>
        )}

        {hasMoreComments && (
          <div className="flex justify-center mt-6">
            <button
              id="load-more-comments"
              onClick={() => fetchMoreComments()}
              disabled={loadingMoreComments}
              className="flex items-center gap-2 px-5 py-2 border border-[#2d323f] rounded-xl text-sm text-[#9ca3af] hover:border-[#d4af37]/40 hover:text-[#d4af37] transition-all disabled:opacity-60"
            >
              {loadingMoreComments
                ? <><RefreshCw className="w-3.5 h-3.5 animate-spin" /> {t('forum:loading')}</>
                : t('forum:load_more_comments')}
            </button>
          </div>
        )}
      </section>
    </main>
  );
}

import { useState, useMemo } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { Chess } from 'chess.js';
import { useTranslation } from 'react-i18next';
import { getLessonById } from '../data/lessons';
import LessonBoard from '../components/LessonBoard';
import StepControls from '../components/StepControls';
import { LessonValidator } from '../engine/lesson/LessonValidator';
import { ProgressTracker } from '../engine/lesson/ProgressTracker';
import { ArrowLeft, CheckCircle2, AlertCircle, Sparkles } from 'lucide-react';

const LessonDetailPage = () => {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const { t } = useTranslation(['learn']);

  const lesson = useMemo(() => getLessonById(lessonId), [lessonId]);

  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [resetCount, setResetCount] = useState(0);
  const [showHint, setShowHint] = useState(false);
  const [feedback, setFeedback] = useState(null);
  const [isStepCompleted, setIsStepCompleted] = useState(false);
  const [lastMove, setLastMove] = useState(null);

  const currentStep = lesson?.steps[currentStepIndex];

  // Derive initial chess instance based on current step and reset trigger
  const { chessInstance, boardFen } = useMemo(() => {
    if (!currentStep) return { chessInstance: null, boardFen: '' };
    const instance = new Chess(currentStep.fen);
    return { chessInstance: instance, boardFen: instance.fen() };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentStep, resetCount]);

  const [currentFen, setCurrentFen] = useState('');
  const activeFen = currentFen || boardFen;

  if (!lesson) {
    return (
      <div className="min-h-screen bg-[#0d0e12] flex flex-col items-center justify-center p-6 text-center text-slate-100">
        <AlertCircle className="w-16 h-16 text-rose-500 mb-4" />
        <h2 className="text-2xl font-bold mb-2">{t('learn:lesson_not_found')}</h2>
        <p className="text-slate-400 mb-6">{t('learn:lesson_not_exist')}</p>
        <Link
          to="/learn"
          className="px-6 py-2.5 rounded-xl bg-amber-400 text-slate-950 font-bold hover:bg-amber-300 transition-colors"
        >
          {t('learn:back_to_lessons')}
        </Link>
      </div>
    );
  }

  const handleMove = (moveCandidate) => {
    if (!chessInstance || isStepCompleted) return false;

    const result = LessonValidator.validateMove(chessInstance, moveCandidate, currentStep);

    if (result.success && result.move) {
      chessInstance.move(result.move);
      setCurrentFen(chessInstance.fen());
      setLastMove({ from: result.move.from, to: result.move.to });
      setIsStepCompleted(true);
      setFeedback({ type: 'success', text: t(`learn:lesson_${lesson.id}_step_${currentStepIndex}_success`, currentStep.successMessage) || t('learn:great_move') });

      ProgressTracker.saveStepProgress(lesson.id, currentStepIndex);

      if (currentStepIndex + 1 >= lesson.steps.length) {
        ProgressTracker.markLessonComplete(lesson.id);
      }
      return true;
    } else {
      setFeedback({ type: 'error', text: result.error || t('learn:wrong_move_try_again') });
      return false;
    }
  };

  const handleNextStep = () => {
    if (currentStepIndex + 1 < lesson.steps.length) {
      setCurrentStepIndex((prev) => prev + 1);
      setCurrentFen('');
      setShowHint(false);
      setFeedback(null);
      setIsStepCompleted(false);
      setLastMove(null);
    } else {
      navigate('/learn');
    }
  };

  const handleRestartStep = () => {
    setResetCount((prev) => prev + 1);
    setCurrentFen('');
    setShowHint(false);
    setFeedback(null);
    setIsStepCompleted(false);
    setLastMove(null);
  };

  return (
    <div className="min-h-screen bg-[#0d0e12] text-slate-100 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto space-y-6">
        {/* Back link & Header */}
        <div className="flex items-center justify-between">
          <Link
            to="/learn"
            className="inline-flex items-center gap-2 text-sm font-semibold text-slate-400 hover:text-amber-400 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" /> {t('learn:back_to_lessons')}
          </Link>
          <span className="text-xs font-bold text-slate-500 uppercase tracking-widest bg-slate-900 border border-slate-800 px-3 py-1 rounded-full">
            {t(`learn:category_${lesson.category.replace(/[^a-zA-Z]/g, '').toLowerCase()}`, lesson.category)}
          </span>
        </div>

        {/* Main Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          {/* Left: Chessboard Column */}
          <div className="lg:col-span-7 flex flex-col items-center justify-center">
            <LessonBoard
              fen={activeFen}
              orientation={currentStep?.orientation || 'white'}
              onMove={handleMove}
              highlightSquares={showHint ? currentStep?.hint?.highlightSquares : []}
              arrows={showHint ? currentStep?.hint?.arrows : []}
              lastMove={lastMove}
              arePiecesDraggable={!isStepCompleted}
            />
          </div>

          {/* Right: Step Description & Controls Panel */}
          <div className="lg:col-span-5 space-y-6">
            <div className="bg-slate-900/80 border border-slate-800 rounded-2xl p-6 shadow-xl space-y-4">
              <div className="flex items-center gap-2">
                <span className="p-2 rounded-xl bg-amber-500/10 text-amber-400 border border-amber-500/20">
                  <Sparkles className="w-5 h-5" />
                </span>
                <h1 className="text-xl font-bold text-white">{t(`learn:lesson_${lesson.id}_title`, lesson.title)}</h1>
              </div>

              <div className="space-y-2 border-t border-slate-800 pt-4">
                <h3 className="text-base font-semibold text-amber-400">{t(`learn:lesson_${lesson.id}_step_${currentStepIndex}_title`, currentStep?.title)}</h3>
                <p className="text-sm text-slate-300 leading-relaxed">{t(`learn:lesson_${lesson.id}_step_${currentStepIndex}_desc`, currentStep?.description)}</p>
              </div>

              {/* Feedback Alert Toast */}
              {feedback && (
                <div
                  className={`p-4 rounded-xl border flex items-start gap-3 transition-all animate-fade-in ${
                    feedback.type === 'success'
                      ? 'bg-emerald-500/10 text-emerald-300 border-emerald-500/30'
                      : 'bg-rose-500/10 text-rose-300 border-rose-500/30'
                  }`}
                >
                  {feedback.type === 'success' ? (
                    <CheckCircle2 className="w-5 h-5 text-emerald-400 shrink-0 mt-0.5" />
                  ) : (
                    <AlertCircle className="w-5 h-5 text-rose-400 shrink-0 mt-0.5" />
                  )}
