import { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useAuth } from '../../auth/context/AuthContext';
import { useSocket } from '../../../shared/socket/useSocket';
import { notificationService } from '../services/notificationService';
import { subscribeToNotifications, NOTIFICATION_EVENTS } from '../socket/notificationSocket';

const NotificationContext = createContext(null);

export const NotificationProvider = ({ children }) => {
  const { isAuthenticated, showToast } = useAuth();
  const socket = useSocket();
  const { connectionStatus, reconnect } = socket;

  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);

  // Load initial notifications and unread count from REST endpoints
  const loadNotificationsData = useCallback(async () => {
    if (!isAuthenticated) return;
    try {
      const listData = await notificationService.getNotifications(0, 20);
      setNotifications(listData.content || []);

      const countData = await notificationService.getUnreadCount();
      setUnreadCount(countData.count || 0);
    } catch (err) {
      console.error('Failed to load initial notifications data', err);
    }
  }, [isAuthenticated]);

  // REST handlers mapping to service calls and keeping state synchronized
  const markAsRead = async (id) => {
    try {
      await notificationService.markRead(id);
      setNotifications((prev) =>
        prev.map((n) => (n.id === id ? { ...n, read: true } : n))
      );
      setUnreadCount((c) => Math.max(0, c - 1));
    } catch (_err) {
      if (showToast) showToast('Failed to mark notification as read.', 'error');
    }
  };

  const markAllAsRead = async () => {
    try {
      await notificationService.markAllRead();
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
      setUnreadCount(0);
      if (showToast) showToast('All notifications marked as read.', 'success');
    } catch (_err) {
      if (showToast) showToast('Failed to mark all as read.', 'error');
    }
  };

  const deleteItem = async (id) => {
    try {
      const itemToDelete = notifications.find((n) => n.id === id);
      await notificationService.deleteNotification(id);
      setNotifications((prev) => prev.filter((n) => n.id !== id));
      if (itemToDelete && !itemToDelete.read) {
        setUnreadCount((c) => Math.max(0, c - 1));
      }
    } catch (_err) {
      if (showToast) showToast('Failed to delete notification.', 'error');
    }
  };

  const clearAll = async () => {
    try {
      await notificationService.deleteAll();
      setNotifications([]);
      setUnreadCount(0);
      if (showToast) showToast('Notification history cleared.', 'success');
    } catch (_err) {
      if (showToast) showToast('Failed to clear notification history.', 'error');
    }
  };

  // REST Data Initialization & Cleanup
  useEffect(() => {
    if (!isAuthenticated) {
      setNotifications([]);
      setUnreadCount(0);
      return;
    }

    loadNotificationsData();
  }, [isAuthenticated, loadNotificationsData]);

  // Subscribe to real-time notification events via notificationSocket adapter
  useEffect(() => {
    if (!isAuthenticated || connectionStatus !== 'CONNECTED') return;

    const unsubscribe = subscribeToNotifications(socket, (event) => {
      if (event.type === NOTIFICATION_EVENTS.NEW) {
        const newNotif = event.payload;
        setNotifications((prev) => [newNotif, ...prev]);
        setUnreadCount((c) => c + 1);
        if (showToast) showToast(newNotif.message, 'success');
      }
    });

    return () => {
      unsubscribe();
    };
  }, [isAuthenticated, socket, showToast, connectionStatus]);

  const value = {
    notifications,
    unreadCount,
    connectionStatus,
    reconnect,
    markAsRead,
    markAllAsRead,
    deleteItem,
    clearAll,
    loadMore: async (page, size) => {
      try {
        const listData = await notificationService.getNotifications(page, size);
        return listData;
      } catch (err) {
        console.error('Failed loading extra notifications page', err);
        return { content: [] };
      }
    },
  };

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within a NotificationProvider');
  }
  return context;
};

import { useState, useEffect } from 'react';
import { useNotifications } from '../context/NotificationContext';
import NotificationItem from '../components/NotificationItem';
import LoadingSkeleton from '../components/LoadingSkeleton';
import EmptyState from '../components/EmptyState';
import { CheckCheck, Trash2, RefreshCw, ArrowDown } from 'lucide-react';

/**
 * NotificationsPage renders the player's notification history log.
 * Header and Footer are provided by ProtectedLayout.
 */
export const NotificationsPage = () => {
  const {
    notifications,
    unreadCount,
    markAsRead,
    markAllAsRead,
    deleteItem,
    clearAll,
    loadMore,
  } = useNotifications();

  const [page, setPage] = useState(0);
  const [extraItems, setExtraItems] = useState([]);
  const [hasMore, setHasMore] = useState(true);
  const [isLoadingMore, setIsLoadingMore] = useState(false);

  // Sync / Reset paging whenever the core context list shifts (e.g. reload or WebSocket push)
  useEffect(() => {
    setPage(0);
    setExtraItems([]);
    setHasMore(notifications.length >= 20);
  }, [notifications]);

  const handleLoadMore = async () => {
    if (isLoadingMore) return;
    setIsLoadingMore(true);
    const nextPage = page + 1;
    try {
      const data = await loadMore(nextPage, 20);
      if (data && data.content && data.content.length > 0) {
        setExtraItems((prev) => [...prev, ...data.content]);
        setPage(nextPage);
        const { number, totalPages } = data.page ?? {};
        setHasMore(number < totalPages - 1);
      } else {
        setHasMore(false);
      }
    } catch (err) {
      console.error('Failed to load more notifications', err);
      setHasMore(false);
    } finally {
      setIsLoadingMore(false);
    }
  };

  // Merge context notifications (page 0 + live web sockets) and loaded pages
  const combined = [...notifications, ...extraItems];
  // Deduplicate items by ID and sort newest first
  const uniqueItems = Array.from(new Map(combined.map((item) => [item.id, item])).values()).sort(
    (a, b) => new Date(b.createdAt) - new Date(a.createdAt)
  );

  return (
    <main className="w-full flex flex-col items-center p-6 md:p-12">
      <div className="w-full max-w-3xl flex flex-col gap-6">
        {/* Header Actions */}
        <div className="flex items-center justify-between border-b border-[#2d323f] pb-4">
          <h2 className="font-playfair text-2xl font-bold text-[#f3f4f6] m-0">
            Notification Arena
          </h2>

          {uniqueItems.length > 0 && (
            <div className="flex items-center gap-3">
              {unreadCount > 0 && (
                <button
                  onClick={markAllAsRead}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-[#2d323f] hover:bg-[#2d323f]/50 hover:text-[#d4af37] text-xs font-semibold text-[#f3f4f6] transition-all cursor-pointer focus:outline-none focus:ring-1 focus:ring-[#d4af37]"
                  title="Mark all as read"
                >
                  <CheckCheck className="w-4 h-4 text-[#d4af37]" />
                  <span>MARK ALL READ</span>
                </button>
              )}

              <button
                onClick={clearAll}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-red-950/40 border border-red-500/30 hover:bg-red-900/40 hover:border-red-500/60 text-xs font-semibold text-red-200 transition-all cursor-pointer focus:outline-none focus:ring-1 focus:ring-red-500"
                title="Clear all history"
              >
                <Trash2 className="w-4 h-4 text-red-400" />
                <span>CLEAR ALL</span>
              </button>
            </div>
          )}
        </div>

        {/* List display */}
        {uniqueItems.length > 0 ? (
          <div className="bg-[#1a1d24] border border-[#2d323f] rounded-xl overflow-hidden shadow-lg divide-y divide-[#2d323f]/50">
            {uniqueItems.map((item) => (
              <NotificationItem
                key={item.id}
                item={item}
                onMarkRead={markAsRead}
                onDelete={deleteItem}
              />
            ))}

            {/* Load More Trigger */}
            {hasMore && (
              <div className="p-4 flex justify-center bg-[#13161c]/30">
                <button
                  onClick={handleLoadMore}
                  disabled={isLoadingMore}
                  className="flex items-center gap-1.5 bg-[#d4af37] text-[#0d0e12] font-bold py-2.5 px-5 rounded-lg hover:bg-[#f3cd57] hover:shadow-[0_4px_12px_rgba(212,175,55,0.25)] transition-all cursor-pointer text-xs disabled:opacity-60 disabled:cursor-not-allowed"
                >
                  {isLoadingMore ? (
                    <RefreshCw className="w-4 h-4 animate-spin" />
                  ) : (
                    <ArrowDown className="w-4 h-4" />
                  )}
                  <span>LOAD MORE NOTIFICATIONS</span>
                </button>
              </div>
            )}
          </div>
        ) : notifications.length === 0 && page === 0 ? (
          <EmptyState />
        ) : (
          <LoadingSkeleton />
        )}
      </div>
    </main>
  );
};

