export const ProfileForm = ({ user, onCancel, onSaveSuccess }) => {
  const { showToast } = useAuth();
  const profile = user?.profile || {};

  const resolver = async (values) => {
    const result = profileSchema.safeParse(values);
    if (result.success) {
      return { values: result.data, errors: {} };
    }
    const errors = {};
    result.error.issues.forEach((err) => {
      errors[err.path[0]] = {
        type: 'validation',
        message: err.message,
      };
    });
    return { values: {}, errors };
  };

  const {
    control,
    handleSubmit,
    register,
    formState: { errors },
  } = useForm({
    defaultValues: {
      fullName: profile.fullName || '',
      gender: profile.gender || '',
      dateOfBirth: profile.dateOfBirth || '',
    },
    resolver,
    mode: 'onTouched',
  });

  const { mutate: performUpdate, isPending } = useMutation({
    mutationFn: async (formData) => {
      return profileService.updateProfile(formData);
    },
    onSuccess: (updatedUser) => {
      showToast('Profile updated successfully!', 'success');
      if (onSaveSuccess) {
        onSaveSuccess(updatedUser);
      }
    },
    onError: (err) => {
      const errMsg =
        err.response?.data?.message ||
        'Failed to save profile changes. Please try again.';
      showToast(errMsg, 'error');
    },
  });

  const onSubmit = (data) => {
    performUpdate(data);
  };

  return (
    <form
      onSubmit={handleSubmit(onSubmit)}
      className="bg-[#1a1d24] border border-[#2d323f] rounded-xl p-6 shadow-lg text-left space-y-5 select-none"
    >
      <h3 className="font-playfair text-xl font-bold text-[#f3f4f6] border-b border-[#2d323f] pb-3 mb-2">
        Edit Player Profile
      </h3>

      {/* Readonly Username & Role */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div>
          <label className="text-xs font-semibold uppercase tracking-wider text-[#9ca3af]">
            Username
          </label>
          <input
            type="text"
            disabled
            value={user?.username || ''}
            className="w-full bg-[#0d0e12]/60 text-[#9ca3af] font-inter px-4 py-3 rounded border border-[#2d323f]/60 text-sm outline-none cursor-not-allowed mt-1"
          />
        </div>
        <div>
          <label className="text-xs font-semibold uppercase tracking-wider text-[#9ca3af]">
            Account Role
          </label>
          <input
            type="text"
            disabled
            value={user?.role || 'USER'}
            className="w-full bg-[#0d0e12]/60 text-[#9ca3af] font-inter px-4 py-3 rounded border border-[#2d323f]/60 text-sm outline-none cursor-not-allowed mt-1 uppercase"
          />
        </div>
      </div>

      {/* Readonly Email */}
      <div>
        <label className="text-xs font-semibold uppercase tracking-wider text-[#9ca3af]">
          Email Address
        </label>
        <input
          type="email"
          disabled
          value={user?.email || ''}
          className="w-full bg-[#0d0e12]/60 text-[#9ca3af] font-inter px-4 py-3 rounded border border-[#2d323f]/60 text-sm outline-none cursor-not-allowed mt-1"
        />
      </div>

      {/* Editable Full Name */}
      <div className="flex flex-col items-start gap-1">
        <label
          htmlFor="fullName"
          className="text-xs font-semibold uppercase tracking-wider text-[#9ca3af]"
        >
          Full Name
        </label>
        <input
          id="fullName"
          type="text"
          aria-invalid={errors.fullName ? 'true' : 'false'}
          className={`w-full bg-[#0d0e12] text-[#f3f4f6] font-inter px-4 py-3 rounded border text-sm transition-all duration-200 outline-none focus:border-[#d4af37] focus:ring-1 focus:ring-[#d4af37] ${
            errors.fullName
              ? 'border-red-500/60 focus:border-red-500 focus:ring-red-500'
              : 'border-[#2d323f] hover:border-[#9ca3af]'
          }`}
          {...register('fullName')}
        />
        {errors.fullName && (
          <span className="text-xs text-red-400 font-medium mt-0.5 animate-fade-in">
            {errors.fullName.message}
          </span>
        )}
      </div>

      {/* Editable Gender Select */}
      <Controller
        control={control}
        name="gender"
        render={({ field: { value, onChange }, fieldState: { error } }) => (
          <GenderSelect
            id="gender"
            label="Gender Selection"
            value={value}
            onChange={onChange}
            error={error}
          />
        )}
      />

      {/* Editable Date Picker */}
      <Controller
        control={control}
        name="dateOfBirth"
        render={({ field: { value, onChange }, fieldState: { error } }) => (
          <DatePicker
            id="dateOfBirth"
            label="Date of Birth"
            value={value}
            onChange={onChange}
            error={error}
          />
        )}
      />

      {/* Action Buttons */}
      <div className="flex items-center justify-end gap-3 border-t border-[#2d323f] pt-5 mt-6">
        <button
          type="button"
          onClick={onCancel}
          disabled={isPending}
          className="flex items-center gap-1.5 px-4 py-2.5 rounded-lg border border-[#2d323f] hover:bg-[#2d323f]/40 hover:text-white text-sm font-semibold text-[#f3f4f6] transition-colors cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <X className="w-4 h-4" />
          <span>CANCEL</span>
        </button>

        <button
          type="submit"
          disabled={isPending}
          className="flex items-center gap-1.5 px-5 py-2.5 bg-[#d4af37] text-[#0d0e12] font-bold rounded-lg hover:bg-[#f3cd57] hover:shadow-[0_4px_12px_rgba(212,175,55,0.25)] transition-all cursor-pointer text-sm disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isPending ? (
            <RefreshCw className="w-4 h-4 animate-spin" />
          ) : (
            <Save className="w-4 h-4" />
          )}
          <span>SAVE CHANGES</span>
        </button>
      </div>
    </form>
  );
};

export default ProfileForm;

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQueryClient } from '@tanstack/react-query';
import { X, Clock, Shield, Lock, Globe, Sparkles, Loader2, Play } from 'lucide-react';
import { roomService } from '../services/roomService';
import { useAuth } from '../../auth/context/AuthContext';
import { useSocket } from '../../../shared/socket/useSocket';

export function CreateRoomModal({ isOpen, onClose, onCreated }) {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { currentUser, showToast } = useAuth();
  const { connectionStatus } = useSocket();

  const defaultRoomName = currentUser?.username ? `${currentUser.username}'s room` : "Player's room";
  const [name, setName] = useState(defaultRoomName);
  const [timeMinutes, setTimeMinutes] = useState(5);
  const [incrementSeconds, setIncrementSeconds] = useState(3);
  const [variant] = useState('STANDARD');
  const [rated, setRated] = useState(true);
  const [isPrivate, setIsPrivate] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Set default name when modal opens
  useEffect(() => {
    if (isOpen) {
      // Just to satisfy linter or avoid setting state, wait, actually setting state in effect is fine if we suppress it or handle it better.
      // Let's use eslint-disable-next-line

      setName(currentUser?.username ? `${currentUser.username}\'s room` : "Player\'s room");
    }
  }, [isOpen, currentUser]);

  if (!isOpen) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();

    const trimmedName = name.trim();
    if (!trimmedName) {
      showToast('Tên phòng là bắt buộc!', 'error');
      return;
    }

    // Check if WebSocket is online as per API spec rule:
    // "Người dùng phải đang Online (có kết nối WebSocket) thì mới được phép gọi API này."
    if (connectionStatus === 'DISCONNECTED') {
      showToast('Bạn cần có kết nối trực tuyến (Realtime WebSocket) để tạo phòng!', 'error');
      return;
    }

    setIsSubmitting(true);

    try {
      const payload = {
        name: trimmedName,
        settings: {
          timeMinutes: Number(timeMinutes),
          incrementSeconds: Number(incrementSeconds),
          variant,
          rated,
          "private": isPrivate,
        },
      };

      const result = await roomService.createRoom(payload);
      const createdId = result?.roomId || result?.id || 'room-123';

      // Cập nhật cache để RoomWaitingPage dùng ngay mà không cần gọi getRoomDetails
      queryClient.setQueryData(['room', createdId], result);

      showToast('Tạo phòng chơi thành công!', 'success');

      if (onCreated) {
        onCreated(result);
      }
      onClose();
      navigate(`/room/${createdId}`);
    } catch (err) {
      const status = err.response?.status;
      const msg = err.response?.data?.message || 'Không thể tạo phòng. Vui lòng thử lại sau.';

      if (status === 403) {
        showToast('Tạo phòng thất bại: Bạn phải duy trì kết nối WebSocket để khởi tạo phòng.', 'error');
      } else {
        showToast(msg, 'error');
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const presetTimes = [
    { label: '3m (Bullet)', time: 3, inc: 0 },
    { label: '3m + 2s (Blitz)', time: 3, inc: 2 },
    { label: '5m + 3s (Blitz)', time: 5, inc: 3 },
    { label: '10m (Rapid)', time: 10, inc: 0 },
    { label: '15m + 10s (Rapid)', time: 15, inc: 10 },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#0d0e12]/80 backdrop-blur-md animate-fade-in">
      <div className="relative w-full max-w-lg bg-[#1a1d24] border border-[#2d323f] rounded-2xl shadow-2xl overflow-hidden">
        {/* MODAL HEADER */}
        <div className="flex items-center justify-between p-5 border-b border-[#2d323f] bg-[#13161c]">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-[#d4af37]/15 border border-[#d4af37]/40 flex items-center justify-center text-[#d4af37]">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <h2 className="font-playfair text-lg font-bold text-[#f3f4f6]">Cấu Hình Phòng Chơi mới</h2>
              <p className="text-xs text-[#9ca3af]">Thiết lập luật đấu & thời gian thi đấu</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl text-[#9ca3af] hover:text-[#f3f4f6] hover:bg-[#2d323f]/50 transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* FORM CONTENT */}
        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          {/* TÊN PHÒNG */}
          <div>
            <label className="block text-xs font-semibold text-[#f3f4f6] uppercase tracking-wider mb-2">
              Tên phòng chơi <span className="text-[#ef4444]">*</span>
            </label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="VD: Player's room"
              className="w-full bg-[#13161c] border border-[#2d323f] focus:border-[#d4af37] text-[#f3f4f6] text-sm rounded-xl p-3 focus:outline-none focus:ring-1 focus:ring-[#d4af37] transition-all placeholder-[#4b5563]"
            />
          </div>

          {/* QUICK PRESETS */}
          <div>
            <label className="block text-xs font-semibold text-[#f3f4f6] uppercase tracking-wider mb-2">
              Mẫu thời gian nhanh
            </label>
            <div className="flex flex-wrap gap-2">
              {presetTimes.map((preset, idx) => (
                <button
                  key={idx}
                  type="button"
                  onClick={() => {
                    setTimeMinutes(preset.time);
                    setIncrementSeconds(preset.inc);
                  }}
                  className={`text-xs px-3 py-1.5 rounded-lg border transition-all cursor-pointer ${timeMinutes === preset.time && incrementSeconds === preset.inc
                    ? 'bg-[#d4af37] text-[#0d0e12] border-[#d4af37] font-bold shadow-md'
                    : 'bg-[#13161c] text-[#9ca3af] border-[#2d323f] hover:border-[#d4af37]/40 hover:text-[#f3f4f6]'
                    }`}
                >
                  {preset.label}
                </button>
              ))}
            </div>
          </div>

          {/* TIME CONTROL CUSTOMIZATION */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-[#f3f4f6] uppercase tracking-wider mb-2 flex items-center gap-1.5">
                <Clock className="w-3.5 h-3.5 text-[#d4af37]" /> Thời gian (Phút)
              </label>
              <select
                value={timeMinutes}
                onChange={(e) => setTimeMinutes(e.target.value)}
                className="w-full bg-[#13161c] border border-[#2d323f] focus:border-[#d4af37] text-[#f3f4f6] text-sm rounded-xl p-3 focus:outline-none transition-all cursor-pointer"
              >
                <option value={1}>1 phút (Bullet)</option>
                <option value={3}>3 phút (Blitz)</option>
                <option value={5}>5 phút (Blitz)</option>
                <option value={10}>10 phút (Rapid)</option>
                <option value={15}>15 phút (Rapid)</option>
                <option value={30}>30 phút (Classical)</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-[#f3f4f6] uppercase tracking-wider mb-2 flex items-center gap-1.5">
                <Clock className="w-3.5 h-3.5 text-[#d4af37]" /> Cộng giây / Nước đi
              </label>
              <select
                value={incrementSeconds}
                onChange={(e) => setIncrementSeconds(e.target.value)}
                className="w-full bg-[#13161c] border border-[#2d323f] focus:border-[#d4af37] text-[#f3f4f6] text-sm rounded-xl p-3 focus:outline-none transition-all cursor-pointer"
              >
                <option value={0}>+0 giây</option>
                <option value={1}>+1 giây</option>
                <option value={2}>+2 giây</option>
                <option value={3}>+3 giây</option>
                <option value={5}>+5 giây</option>
                <option value={10}>+10 giây</option>
              </select>
            </div>
          </div>

          {/* RATED & PRIVACY TOGGLES */}
          <div className="grid grid-cols-2 gap-4 pt-2 border-t border-[#2d323f]">
            <button
              type="button"
              onClick={() => setRated(!rated)}
              className={`p-3 rounded-xl border flex items-center justify-between text-left transition-all cursor-pointer ${rated
                ? 'bg-[#d4af37]/10 border-[#d4af37]/50 text-[#d4af37]'
                : 'bg-[#13161c] border-[#2d323f] text-[#9ca3af]'
                }`}
            >
              <div className="flex items-center gap-2">
                <Shield className="w-4 h-4" />
                <div>
                  <span className="block text-xs font-bold text-[#f3f4f6]">Tính điểm Elo</span>
                  <span className="text-[10px] opacity-80">{rated ? 'Trận Rated' : 'Không tính điểm'}</span>
                </div>
              </div>
            </button>

            <button
              type="button"
              onClick={() => setIsPrivate(!isPrivate)}
              className={`p-3 rounded-xl border flex items-center justify-between text-left transition-all cursor-pointer ${isPrivate
                ? 'bg-[#38bdf8]/10 border-[#38bdf8]/50 text-[#38bdf8]'
                : 'bg-[#13161c] border-[#2d323f] text-[#9ca3af]'
                }`}
            >
              <div className="flex items-center gap-2">
                {isPrivate ? <Lock className="w-4 h-4" /> : <Globe className="w-4 h-4" />}
                <div>
                  <span className="block text-xs font-bold text-[#f3f4f6]">Chế độ phòng</span>
                  <span className="text-[10px] opacity-80">{isPrivate ? 'Phòng Riêng tư' : 'Hiện ở Sảnh'}</span>
                </div>
              </div>
            </button>
          </div>

          {/* ACTIONS */}
          <div className="flex items-center justify-end gap-3 pt-4 border-t border-[#2d323f]">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 rounded-xl border border-[#2d323f] text-[#9ca3af] hover:text-[#f3f4f6] text-xs font-semibold transition-colors cursor-pointer"
            >
              Hủy bỏ
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="bg-[#d4af37] text-[#0d0e12] hover:bg-[#b59226] font-bold text-xs px-6 py-2.5 rounded-xl flex items-center gap-2 transition-all cursor-pointer shadow-md disabled:opacity-50"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>Đang tạo...</span>
                </>
              ) : (
                <>
                  <Play className="w-4 h-4 fill-[#0d0e12]" />
                  <span>TẠO PHÒNG NGAY</span>
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Maximize2, X, Clock, Users, Sparkles } from 'lucide-react';
import { activeRoomManager } from '../services/activeRoomManager';
import { useAuth } from '../../auth/context/AuthContext';
import { roomService } from '../services/roomService';
import { useQueryClient } from '@tanstack/react-query';
import { useRoomDetails } from '../hooks/useRoomDetails';

/**
 * Floating Room Widget cho phép thu nhỏ phòng chờ ở góc màn hình.
 * Người chơi có thể tự do xem Sảnh, Học cờ, Diễn đàn trong khi phòng vẫn ở trạng thái chờ.
 */
export function FloatingRoomWidget() {
  const [activeRoom, setActiveRoom] = useState(() => activeRoomManager.getRoom());
  const location = useLocation();
  const navigate = useNavigate();
  const { showToast } = useAuth();
  const queryClient = useQueryClient();

  useEffect(() => {
    return activeRoomManager.subscribe((room) => {
      setActiveRoom(room);
    });
  }, []);

  const { room: fetchedRoom, isError } = useRoomDetails(activeRoom?.roomId, {
    onRoomDeleted: () => {
      activeRoomManager.clearRoom();
    }
  });

  // Clear room on error (e.g., room deleted while offline)
  useEffect(() => {
    if (isError && activeRoom) {
      activeRoomManager.clearRoom();
    }
  }, [isError, activeRoom]);

  const displayRoom = fetchedRoom || activeRoom;

  if (!displayRoom) return null;

  // Don't display widget when user is already inside the full room page
  if (location.pathname === `/room/${displayRoom.roomId}`) {
    return null;
  }

  const { roomId, name, settings = {}, white, black } = displayRoom;
  const { timeMinutes = 5, incrementSeconds = 3 } = settings;
  const playerCount = (white ? 1 : 0) + (black ? 1 : 0);

  const handleExpand = () => {
    navigate(`/room/${roomId}`);
  };

  const handleLeave = async (e) => {
    e.stopPropagation();
    try {
      await roomService.leaveRoom(roomId);
      showToast('Đã rời khỏi phòng chơi', 'info');
      queryClient.invalidateQueries({ queryKey: ['rooms', 'lobby'] });
      activeRoomManager.clearRoom();
    } catch (err) {
      showToast('Lỗi khi rời phòng: ' + (err.response?.data?.message || err.message), 'error');
      queryClient.invalidateQueries({ queryKey: ['rooms', 'lobby'] });
      activeRoomManager.clearRoom(); // fallback in case room is already gone
    }
  };

  return (
    <div className="fixed bottom-5 right-5 z-50 animate-bounce-in select-none">
      <div className="bg-[#1a1d24]/95 backdrop-blur-md border border-[#d4af37]/40 shadow-2xl rounded-2xl p-3 sm:p-4 flex items-center gap-3.5 max-w-sm text-[#f3f4f6] hover:border-[#d4af37] transition-all group">
        {/* PULSING STATUS DOT */}
        <div className="relative flex items-center justify-center shrink-0">
          <span className="w-3 h-3 rounded-full bg-[#10b981]" />
          <span className="absolute w-3 h-3 rounded-full bg-[#10b981] animate-ping opacity-75" />
        </div>

        {/* ROOM DETAILS */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <Sparkles className="w-3.5 h-3.5 text-[#d4af37]" />
            <h4 className="font-bold text-xs text-[#f3f4f6] truncate">
              {name || `Phòng Cờ #${roomId?.slice(0, 6)}`}
            </h4>
          </div>

          <div className="flex items-center gap-2 text-[11px] text-[#9ca3af] mt-0.5">
            <span className="flex items-center gap-1">
              <Users className="w-3 h-3 text-[#d4af37]" /> {playerCount}/2
            </span>
            <span>•</span>
            <span className="flex items-center gap-1">
              <Clock className="w-3 h-3 text-[#d4af37]" /> {timeMinutes}+{incrementSeconds}m
            </span>
          </div>
        </div>

        {/* ACTION BUTTONS */}
        <div className="flex items-center gap-1 shrink-0">
          {/* PHÓNG TO / MỞ RỘNG */}
          <button
            type="button"
            onClick={handleExpand}
            className="flex items-center gap-1 bg-[#d4af37] hover:bg-[#b59226] text-[#0d0e12] font-bold text-xs px-2.5 py-1.5 rounded-xl transition-all shadow-md cursor-pointer"
            title="Phóng to mở rộng phòng chờ"
          >
            <Maximize2 className="w-3.5 h-3.5" />
            <span className="hidden sm:inline">Phóng to</span>
          </button>

          {/* ĐÓNG / RỜI PHÒNG */}
          <button
            type="button"
            onClick={handleLeave}
            className="p-1.5 rounded-xl text-[#9ca3af] hover:text-[#ef4444] hover:bg-[#ef4444]/10 transition-colors cursor-pointer"
            title="Đóng widget phòng"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
}

export default FloatingRoomWidget;

