import { User, Crown, CheckCircle2, Plus } from 'lucide-react';
import { useAuth } from '../../auth/context/AuthContext';

export function RoomSeats({ room, onSeatChange }) {
  const { currentUser } = useAuth();
  if (!room) return null;

  const { white, black, host, status } = room;
  const _isHost = currentUser?.id === host?.id;
  const isWaiting = status === 'WAITING';

  const isUserWhite = currentUser && white && currentUser.id === white.id;
  const isUserBlack = currentUser && black && currentUser.id === black.id;

  const renderSeat = (player, side, sideName, bgBadge) => {
    const isOccupied = Boolean(player);
    const isCurrentHost = player && player.id === host?.id;

    return (
      <div className="flex-1 bg-[#13161c] border border-[#2d323f] rounded-2xl p-4 flex flex-col items-center justify-between text-center relative overflow-hidden group">
        {/* SIDE LABEL BADGE */}
        <div className="w-full flex items-center justify-between border-b border-[#2d323f]/60 pb-2 mb-3">
          <span className={`text-[10px] font-bold uppercase tracking-wider px-2.5 py-0.5 rounded-full border ${bgBadge}`}>
            Quân {sideName}
          </span>
          {isCurrentHost && (
            <span className="flex items-center gap-1 text-[10px] font-bold text-[#d4af37] bg-[#d4af37]/10 px-2 py-0.5 rounded-full border border-[#d4af37]/30">
              <Crown className="w-3 h-3" /> Host
            </span>
          )}
        </div>

        {/* PLAYER AVATAR & INFO */}
        <div className="my-2 space-y-2 flex flex-col items-center">
          <div className="relative">
            <div className="w-16 h-16 rounded-2xl bg-[#1a1d24] border-2 border-[#d4af37]/40 flex items-center justify-center text-[#d4af37] shadow-inner overflow-hidden">
              {isOccupied && player.avatarUrl ? (
                <img src={player.avatarUrl} alt={player.username} className="w-full h-full object-cover" />
              ) : isOccupied ? (
                <User className="w-8 h-8 text-[#d4af37]" />
              ) : (
                <User className="w-8 h-8 text-[#4b5563]" />
              )}
            </div>
            {isOccupied && (
              <span className="absolute -bottom-1 -right-1 w-4 h-4 bg-[#10b981] border-2 border-[#13161c] rounded-full" />
            )}
          </div>

          <div>
            <h4 className="font-bold text-sm text-[#f3f4f6]">
              {isOccupied ? player.username : 'Ghế trống'}
            </h4>
            <p className="text-[11px] text-[#9ca3af]">
              {isOccupied ? `Elo: ${player.elo || 1500}` : 'Đang chờ người chơi...'}
            </p>
          </div>
        </div>

        {/* ACTION BUTTON */}
        {isWaiting && (
          <div className="mt-3 w-full">
            {!isOccupied ? (
              <button
                type="button"
                onClick={() => onSeatChange && onSeatChange(side)}
                className="w-full bg-[#d4af37]/15 hover:bg-[#d4af37] text-[#d4af37] hover:text-[#0d0e12] border border-[#d4af37]/40 font-bold text-xs py-2 px-3 rounded-xl transition-all flex items-center justify-center gap-1.5 cursor-pointer shadow-sm"
              >
                <Plus className="w-4 h-4" />
                <span>Ngồi ghế {sideName}</span>
              </button>
            ) : (isUserWhite && side === 'WHITE') || (isUserBlack && side === 'BLACK') ? (
              <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#10b981]">
                <CheckCircle2 className="w-3.5 h-3.5" /> Bạn đang ở đây
              </span>
            ) : null}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col sm:flex-row items-center gap-4 w-full">
      {/* WHITE SEAT */}
      {renderSeat(
        white,
        'WHITE',
        'Trắng',
        'bg-[#f3f4f6]/10 text-[#f3f4f6] border-[#f3f4f6]/30'
      )}

      {/* VS ICON / SWAP BUTTON */}
      <div className="flex flex-col items-center justify-center gap-1 shrink-0">
        <div className="w-10 h-10 rounded-full bg-[#1a1d24] border border-[#2d323f] flex items-center justify-center font-playfair font-black text-sm text-[#d4af37] shadow-md">
          VS
        </div>
      </div>

      {/* BLACK SEAT */}
      {renderSeat(
        black,
        'BLACK',
        'Đen',
        'bg-[#2d323f] text-[#9ca3af] border-[#4b5563]'
      )}
    </div>
  );
}

import { Eye, Users } from 'lucide-react';

export function RoomSpectators({ spectators = [] }) {
  return (
    <div className="bg-[#13161c] border border-[#2d323f] rounded-2xl p-4 space-y-3">
      <div className="flex items-center justify-between border-b border-[#2d323f]/60 pb-2">
        <div className="flex items-center gap-2 text-xs font-bold text-[#f3f4f6]">
          <Eye className="w-4 h-4 text-[#38bdf8]" />
          <span>Khán giả đang xem</span>
        </div>
        <span className="text-xs font-semibold text-[#38bdf8] bg-[#38bdf8]/10 px-2.5 py-0.5 rounded-full border border-[#38bdf8]/30">
          {spectators.length} người
        </span>
      </div>

      {spectators.length === 0 ? (
        <div className="py-4 text-center text-xs text-[#9ca3af] space-y-1">
          <Users className="w-5 h-5 mx-auto text-[#4b5563]" />
          <p>Chưa có khán giả nào vào xem</p>
        </div>
      ) : (
        <div className="flex flex-wrap gap-2 pt-1 max-h-28 overflow-y-auto">
          {spectators.map((spec, idx) => (
            <div
              key={spec.id || idx}
              className="flex items-center gap-2 bg-[#1a1d24] border border-[#2d323f] rounded-xl px-2.5 py-1 text-xs text-[#f3f4f6]"
            >
              <div className="w-5 h-5 rounded-full bg-[#13161c] flex items-center justify-center text-[10px] text-[#38bdf8] font-bold">
                {spec.username?.[0]?.toUpperCase() || 'U'}
              </div>
              <span className="font-semibold">{spec.username}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { useParams, useNavigate, useBlocker } from 'react-router-dom';
import { Play, LogOut, Loader2, AlertCircle, ShieldAlert, Minimize2, X } from 'lucide-react';
import { useRoomDetails } from '../hooks/useRoomDetails';
import { RoomHeader } from '../components/RoomHeader';
import { RoomSeats } from '../components/RoomSeats';
import { RoomSpectators } from '../components/RoomSpectators';
import { RoomChat } from '../components/RoomChat';
import { useAuth } from '../../auth/context/AuthContext';
import { roomService } from '../services/roomService';
import { activeRoomManager } from '../services/activeRoomManager';
import { useQueryClient } from '@tanstack/react-query';

import { useTranslation } from 'react-i18next';

export function RoomWaitingPage() {
  const { t } = useTranslation(['room']);
  const { roomId } = useParams();
  const navigate = useNavigate();
  const { currentUser, showToast } = useAuth();
  const queryClient = useQueryClient();
  const { room, isLoading, isError, refetch } = useRoomDetails(roomId, {
    onRoomDeleted: () => {
      bypassBlockerRef.current = true;
      navigate('/dashboard');
    }
  });

  const [isStarting, setIsStarting] = useState(false);
  const bypassBlockerRef = useRef(false);

  // Blocker to intercept navigation attempts (Back button, links, etc.)
  const blocker = useBlocker(
    ({ currentLocation, nextLocation }) =>
      currentLocation.pathname !== nextLocation.pathname && !bypassBlockerRef.current
  );

  const handleConfirmLeave = async () => {
    try {
      await roomService.leaveRoom(roomId);
      showToast(t('room:leaveRoomSuccess', 'Left the room'), 'info');
      queryClient.invalidateQueries({ queryKey: ['rooms', 'lobby'] });
    } catch (err) {
      showToast(t('room:leaveRoomError', 'Error leaving room: ') + (err.response?.data?.message || err.message), 'error');
      queryClient.invalidateQueries({ queryKey: ['rooms', 'lobby'] });
    }
    // eslint-disable-next-line react-hooks/immutability
    bypassBlockerRef.current = true;
    if (blocker.state === 'blocked') {
      blocker.proceed();
    } else {
      navigate('/dashboard');
    }
  };

  const handleConfirmMinimize = () => {
    activeRoomManager.setRoom(room);
    showToast(t('room:minimizeSuccess', 'Room minimized to screen corner!'), 'info');
    // eslint-disable-next-line react-hooks/immutability
    bypassBlockerRef.current = true;
    if (blocker.state === 'blocked') {
      blocker.proceed();
    } else {
      navigate('/dashboard');
    }
  };

  const handleCancelNavigation = () => {
    if (blocker.state === 'blocked') {
      blocker.reset();
    }
  };

  // Cleanup bypass flag on mount
  useEffect(() => {
    // eslint-disable-next-line react-hooks/immutability
    bypassBlockerRef.current = false;
  }, []);

  if (isLoading) {
    return (
      <div className="min-h-[80vh] flex flex-col items-center justify-center p-6 space-y-4 text-center">
        <Loader2 className="w-10 h-10 animate-spin text-[#d4af37]" />
        <p className="text-sm font-semibold text-[#f3f4f6]">{t('room:loadingLobby', 'Loading lobby...')} #{roomId?.slice(0, 8)}</p>
      </div>
    );
  }

  if (isError || !room) {
    return (
      <div className="min-h-[80vh] flex flex-col items-center justify-center p-6 text-center max-w-md mx-auto space-y-4">
        <div className="w-12 h-12 rounded-2xl bg-[#ef4444]/10 border border-[#ef4444]/30 flex items-center justify-center text-[#ef4444]">
          <ShieldAlert className="w-6 h-6" />
        </div>
        <h2 className="text-lg font-bold text-[#f3f4f6]">{t('room:loadLobbyError', 'Failed to load lobby data.')}</h2>
        <p className="text-xs text-[#9ca3af]">{t('room:noRoomsDesc', 'Create the first room to start playing!')}</p>
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={() => refetch()}
            className="px-4 py-2 bg-[#13161c] border border-[#2d323f] rounded-xl text-xs font-bold text-[#d4af37] hover:bg-[#2d323f] cursor-pointer"
          >
            {t('room:retry', 'Retry')}
          </button>
          <button
            type="button"
            onClick={() => navigate('/dashboard')}
            className="px-4 py-2 bg-[#d4af37] text-[#0d0e12] rounded-xl text-xs font-bold hover:bg-[#b59226] cursor-pointer"
          >
            {t('room:joinPlay', 'PLAY')}
          </button>
        </div>
      </div>
    );
  }

  const isHost = currentUser?.id === room.host?.id;
  const canStartGame = room.white && room.black && room.status === 'WAITING';

  const handleStartGame = async () => {
    setIsStarting(true);
    showToast(t('room:creating', 'Creating...'), 'success');
    setTimeout(() => {
      setIsStarting(false);
      // In future: navigate to actual board play route e.g. /game/:gameId
    }, 1200);
  };

  const handleSeatChange = () => {
    showToast(t('room:sitWhite', 'Sit as White'), 'success');
  };

  return (
    <>
      <div className="container mx-auto px-4 py-6 max-w-6xl space-y-6 relative">
        {/* ROOM HEADER */}
        <RoomHeader room={room} onMinimize={handleConfirmMinimize} />

        {/* ACTION BUTTONS (START GAME & LEAVE ROOM) MOVED TO TOP */}
        <div className="flex flex-col sm:flex-row gap-4">
          {isHost ? (
            <button
              type="button"
              onClick={handleStartGame}
              disabled={!canStartGame || isStarting}
              className="flex-1 bg-[#d4af37] text-[#0d0e12] hover:bg-[#b59226] font-bold text-sm py-3.5 px-4 rounded-xl transition-all shadow-lg flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isStarting ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>{t('room:creating', 'Creating...')}</span>
                </>
              ) : (
                <>
                  <Play className="w-4 h-4 fill-[#0d0e12]" />
                  <span>{t('room:joinPlay', 'PLAY')}</span>
                </>
              )}
            </button>
          ) : (
            <div className="flex-1 p-3 bg-[#13161c] border border-[#2d323f] rounded-xl text-center text-xs text-[#9ca3af] flex items-center justify-center gap-2">
              <AlertCircle className="w-4 h-4 text-[#d4af37]" />
              <span>{t('room:waitingPlayer', 'Waiting for player...')}</span>
            </div>
          )}

          <button
            type="button"
            onClick={handleConfirmLeave}
            className="sm:w-auto w-full bg-[#13161c] border border-[#2d323f] hover:bg-[#ef4444]/10 hover:border-[#ef4444]/40 hover:text-[#ef4444] text-[#9ca3af] font-semibold text-xs py-2.5 px-6 rounded-xl transition-all flex items-center justify-center gap-2 cursor-pointer"
          >
            <LogOut className="w-4 h-4" />
            <span>{t('room:leaveRoomSuccess', 'Leave room').replace('Left the', 'Leave')}</span>
          </button>
        </div>

        {/* MAIN CONTENT WORKSPACE */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
          {/* SEATS & SPECTATORS SECTION (LEFT) */}
          <div className="lg:col-span-5 space-y-6 flex flex-col h-full">
            {/* SEATS (WHITE vs BLACK) */}
            <div className="bg-[#1a1d24] border border-[#2d323f] rounded-2xl p-5 shadow-lg space-y-4">
              <h3 className="text-xs font-bold text-[#f3f4f6] uppercase tracking-wider border-b border-[#2d323f] pb-2">
                {t('room:playerList', 'Player List')}
              </h3>
              <RoomSeats room={room} onSeatChange={handleSeatChange} />
            </div>

            {/* SPECTATORS LIST */}
            <RoomSpectators spectators={room.spectators || []} />
          </div>

          {/* CHAT SECTION (RIGHT) */}
          <div className="lg:col-span-7 h-full min-h-[500px]">
            <RoomChat roomId={roomId} room={room} />
          </div>
        </div>
      </div>

      {/* BLOCKER CONFIRMATION MODAL */}
      {blocker.state === 'blocked' && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#0d0e12]/80 backdrop-blur-sm p-4">
          <div className="bg-[#1a1d24] border border-[#2d323f] rounded-2xl p-6 shadow-2xl max-w-sm w-full space-y-6 relative animate-in fade-in zoom-in duration-200">
            <button
              onClick={handleCancelNavigation}
              className="absolute top-4 right-4 text-[#9ca3af] hover:text-[#f3f4f6] transition-colors cursor-pointer"
            >
              <X className="w-5 h-5" />
            </button>
            <div className="text-center space-y-2">
              <div className="w-12 h-12 bg-[#d4af37]/10 rounded-full flex items-center justify-center mx-auto mb-4 border border-[#d4af37]/30">
                <AlertCircle className="w-6 h-6 text-[#d4af37]" />
              </div>
              <h3 className="text-lg font-bold text-[#f3f4f6]">{t('room:expandWidgetTitle', 'Expand room widget')}</h3>
              <p className="text-sm text-[#9ca3af]">
                {t('room:waitingPlayer', 'Waiting for player...')}
              </p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={handleConfirmLeave}
                className="flex flex-col items-center justify-center gap-2 bg-[#13161c] hover:bg-[#ef4444]/10 border border-[#2d323f] hover:border-[#ef4444]/40 text-[#9ca3af] hover:text-[#ef4444] p-3 rounded-xl transition-all cursor-pointer"
              >
                <LogOut className="w-5 h-5" />
                <span className="text-xs font-semibold">{t('room:leaveRoomSuccess', 'Leave room').replace('Left the', 'Leave')}</span>
              </button>
              <button
                type="button"
                onClick={handleConfirmMinimize}
                className="flex flex-col items-center justify-center gap-2 bg-[#d4af37] text-[#0d0e12] hover:bg-[#b59226] border border-[#d4af37] p-3 rounded-xl transition-all cursor-pointer"
              >
                <Minimize2 className="w-5 h-5" />
                <span className="text-xs font-bold">{t('room:minimize', 'Minimize')}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default RoomWaitingPage;

/* eslint-disable react-refresh/only-export-components */
import { createContext, useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../../features/auth/context/AuthContext';
import { stompClientManager } from './stompClient';
import { mockSocketManager } from './mockSocket';

export const SocketContext = createContext(null);

const isMockMode = import.meta.env.DEV && import.meta.env.VITE_USE_MOCK_API === 'true';
const activeManager = isMockMode ? mockSocketManager : stompClientManager;

export const SocketProvider = ({ children }) => {
  const { isAuthenticated, showToast } = useAuth();
  const [connectionStatus, setConnectionStatus] = useState(activeManager.getStatus());
  const [reconnectCount, setReconnectCount] = useState(0);
  const wasConnectedRef = useRef(false);

  // Status listener synchronization & Toast alerts
  useEffect(() => {
    const unsubscribeStatus = activeManager.onStatusChange((newStatus) => {
      setConnectionStatus(newStatus);

      if (newStatus === 'DISCONNECTED') {
        if (wasConnectedRef.current && showToast) {
          showToast('Mất kết nối với máy chủ realtime.', 'error');
        }
        wasConnectedRef.current = false;
      } else if (newStatus === 'CONNECTED') {
        if (!wasConnectedRef.current && showToast) {
          showToast('Đã kết nối máy chủ realtime thành công.', 'success');
        }
        wasConnectedRef.current = true;
      }
    });
    return () => unsubscribeStatus();
  }, [showToast]);

  const connect = useCallback(() => {
    if (!isAuthenticated) return;
    activeManager.connect();
  }, [isAuthenticated]);

  const disconnect = useCallback(() => {
    wasConnectedRef.current = false;
    activeManager.disconnect();
  }, []);

  const reconnect = useCallback(() => {
    if (!isAuthenticated) return;
    if (showToast) {
      showToast('Đang thử kết nối lại máy chủ realtime...', 'info');
    }
    wasConnectedRef.current = false;
    activeManager.disconnect();
    setReconnectCount((c) => c + 1);
  }, [isAuthenticated, showToast]);

  // Lifecycle management based on authentication & reconnect trigger
  useEffect(() => {
    if (!isAuthenticated) {
      disconnect();
      return;
    }

    connect();

    return () => {
      // Ponytail: cleanup connection on unmount or user logout
      disconnect();
    };
  }, [isAuthenticated, reconnectCount, connect, disconnect]);

  // Global automatic presence heartbeat interval
  useEffect(() => {
    if (!isAuthenticated || connectionStatus !== 'CONNECTED') {
      return;
    }

    const envVal = import.meta.env.VITE_HEARTBEAT_INTERVAL_MS || import.meta.env.VITE_HEARTBEAT_INTERVAL_SECONDS;
    const parsedVal = Number(envVal);
    // If set in env as seconds (< 1000), convert to ms. Fallback to 10000ms (10s)
    const intervalMs = (!isNaN(parsedVal) && parsedVal > 0)
      ? (parsedVal < 1000 ? parsedVal * 1000 : parsedVal)
      : 10000;

    activeManager.send('/app/presence.heartbeat');

    const intervalId = setInterval(() => {
      activeManager.send('/app/presence.heartbeat');
    }, intervalMs);

    return () => {
      clearInterval(intervalId);
    };
  }, [isAuthenticated, connectionStatus]);

  const subscribe = useCallback((destination, callback, headers) => {
    return activeManager.subscribe(destination, callback, headers);
  }, []);

  const unsubscribe = useCallback((subId) => {
    activeManager.unsubscribe(subId);
  }, []);

  const send = useCallback((destination, payload, headers) => {
    return activeManager.send(destination, payload, headers);
  }, []);

  const value = {
    connect,
    disconnect,
    reconnect,
    subscribe,
    unsubscribe,
    send,
    connectionStatus,
    stompClient: activeManager,
  };

  return <SocketContext.Provider value={value}>{children}</SocketContext.Provider>;
};
